import Foundation
import Dispatch

// MARK: - Email Service with Audit Logging

final class AuditEntry: @unchecked Sendable {
    let timestamp: Date
    let message: String
    private let metadataLock = NSLock()
    private var _metadata: [String: String]

    var metadata: [String: String] {
        get { metadataLock.lock(); defer { metadataLock.unlock() }; return _metadata }
        set { metadataLock.lock(); defer { metadataLock.unlock() }; _metadata = newValue }
    }

    func updateMetadata(key: String, value: String) {
        metadataLock.lock()
        defer { metadataLock.unlock() }
        _metadata[key] = value
    }

    init(message: String, metadata: [String: String] = [:]) {
        self.timestamp = Date()
        self.message = message
        self._metadata = metadata
    }
}

protocol AuditLogDelegate: AnyObject {
    func didCompleteAudit(entry: AuditEntry)
}

final class AuditLogger {
    private var pendingEntries: [AuditEntry] = []
    private let queue = DispatchQueue(label: "com.email.audit", attributes: .concurrent)
    weak var delegate: AuditLogDelegate?

    func enqueue(entry: AuditEntry) {
        queue.async(flags: .barrier) {
            self.pendingEntries.append(entry)
        }
    }

    func flush() {
        queue.async(flags: .barrier) {
            let entries = self.pendingEntries
            self.pendingEntries.removeAll()
            for entry in entries {
                self.persist(entry: entry)
            }
        }
    }

    private func persist(entry: AuditEntry) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) { [weak self] in
            entry.updateMetadata(key: "persisted", value: "true")
            self?.delegate?.didCompleteAudit(entry: entry)
        }
    }
}

final class EmailMessage {
    let to: String
    let from: String
    let subject: String
    let body: String
    var auditRef: AuditEntry?

    init(to: String, from: String, subject: String, body: String) {
        self.to = to
        self.from = from
        self.subject = subject
        self.body = body
    }
}

final class ConnectionPool {
    private var connections: [SMTPConnection] = []
    private let poolQueue = DispatchQueue(label: "com.email.pool")

    func acquire() -> SMTPConnection {
        return poolQueue.sync {
            if let conn = connections.popLast() {
                return conn
            }
            return SMTPConnection()
        }
    }

    func release(_ conn: SMTPConnection) {
        poolQueue.sync {
            connections.append(conn)
        }
    }
}

final class SMTPConnection {
    private var isActive = true

    func send(data: Data, completion: @escaping (Bool) -> Void) {
        DispatchQueue.global().async {
            Thread.sleep(forTimeInterval: 0.05)
            completion(self.isActive)
        }
    }

    func invalidate() {
        isActive = false
    }
}

final class EmailService: AuditLogDelegate {
    private let pool = ConnectionPool()
    private let logger = AuditLogger()
    private let sendQueue = DispatchQueue(label: "com.email.send")
    private var inflightMessages: [ObjectIdentifier: EmailMessage] = [:]
    private var retainedAuditEntries: [ObjectIdentifier: AuditEntry] = [:]

    init() {
        logger.delegate = self
    }

    func sendEmail(_ message: EmailMessage, completion: @escaping (Result<Void, Error>) -> Void) {
        let entry = AuditEntry(message: "Sending email to \(message.to)",
                               metadata: ["subject": message.subject, "from": message.from])
        message.auditRef = entry
        logger.enqueue(entry: entry)

        let conn = pool.acquire()
        let msgId = ObjectIdentifier(message)

        sendQueue.async {
            self.inflightMessages[msgId] = message
            self.retainedAuditEntries[msgId] = entry
        }

        let payload = "\(message.from)|\(message.to)|\(message.subject)|\(message.body)".data(using: .utf8)!

        conn.send(data: payload) { [weak self] success in
            guard let self = self else { return }

            self.sendQueue.async {
                let msg = self.inflightMessages.removeValue(forKey: msgId)
                let auditEntry = self.retainedAuditEntries.removeValue(forKey: msgId)
                self.pool.release(conn)

                if success {
                    self.finalizeAudit(for: msg, entry: auditEntry)
                    completion(.success(()))
                } else {
                    auditEntry?.updateMetadata(key: "status", value: "failed")
                    completion(.failure(NSError(domain: "SMTP", code: -1)))
                }
            }
        }

        logger.flush()
    }

    private func finalizeAudit(for message: EmailMessage?, entry: AuditEntry?) {
        guard let auditEntry = entry else { return }
        auditEntry.updateMetadata(key: "status", value: "delivered")
        message?.auditRef = nil
    }

    // MARK: - AuditLogDelegate
    func didCompleteAudit(entry: AuditEntry) {
        sendQueue.async {
            let status = entry.metadata["status"] ?? "unknown"
            print("Audit completed: \(entry.message) - status: \(status)")
        }
    }

    func cancelAll() {
        sendQueue.async {
            let entries = Array(self.retainedAuditEntries.values)
            self.inflightMessages.removeAll()
            self.retainedAuditEntries.removeAll()

            for entry in entries {
                entry.updateMetadata(key: "status", value: "cancelled")
            }
        }
    }
}

// MARK: - Usage
let service = EmailService()
let email = EmailMessage(to: "user@example.com", from: "system@app.com",
                         subject: "Welcome", body: "Hello!")
service.sendEmail(email) { result in
    switch result {
    case .success: print("Sent")
    case .failure(let e): print("Failed: \(e)")
    }
}
service.cancelAll()
RunLoop.current.run(until: Date().addingTimeInterval(1))
